const items = $input.all();
const now = new Date();
const SLA_HOURS = 4;
const results = [];
const breached = [];
const warning = [];

for (const item of items) {
  const emailDate = new Date(item.json.date || item.json.internalDate);
  const ageMs = now - emailDate;
  const ageHours = ageMs / (1000 * 60 * 60);

  const from = item.json.from || 'Unknown';
  const subject = item.json.subject || 'No Subject';

  if (ageHours > SLA_HOURS) {
    breached.push({
      from: from,
      subject: subject,
      ageHours: Math.round(ageHours * 10) / 10,
      receivedAt: emailDate.toISOString(),
      slaStatus: 'BREACHED'
    });
  } else if (ageHours > SLA_HOURS * 0.75) {
    warning.push({
      from: from,
      subject: subject,
      ageHours: Math.round(ageHours * 10) / 10,
      receivedAt: emailDate.toISOString(),
      slaStatus: 'WARNING'
    });
  }
}

const allAlerts = [...breached, ...warning];

if (allAlerts.length === 0) {
  return [{ json: { hasAlerts: false, breachedCount: 0, warningCount: 0, message: 'All emails within SLA' } }];
}

let alertTable = '';
for (const alert of allAlerts) {
  const color = alert.slaStatus === 'BREACHED' ? '#ef4444' : '#f59e0b';
  alertTable += `<tr><td style="padding:6px;border:1px solid #ddd;color:${color};font-weight:bold;">${alert.slaStatus}</td><td style="padding:6px;border:1px solid #ddd;">${alert.from}</td><td style="padding:6px;border:1px solid #ddd;">${alert.subject}</td><td style="padding:6px;border:1px solid #ddd;">${alert.ageHours}h</td></tr>`;
}

const html = `<div style="font-family:Arial,sans-serif;">
  <h2 style="color:#ef4444;">Email SLA Alert</h2>
  <p>Breached: ${breached.length} | Warning: ${warning.length}</p>
  <table style="width:100%;border-collapse:collapse;">
    <thead><tr style="background:#f3f4f6;"><th style="padding:6px;border:1px solid #ddd;">Status</th><th style="padding:6px;border:1px solid #ddd;">From</th><th style="padding:6px;border:1px solid #ddd;">Subject</th><th style="padding:6px;border:1px solid #ddd;">Age</th></tr></thead>
    <tbody>${alertTable}</tbody>
  </table>
</div>`;

return [{
  json: {
    hasAlerts: true,
    breachedCount: breached.length,
    warningCount: warning.length,
    htmlReport: html,
    checkedAt: now.toISOString(),
    slaHours: SLA_HOURS
  }
}];
